def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    elephant_patches = image_patch.find("elephant")
    desert_patches = image_patch.find("desert")

    if not elephant_patches:
        return image_patch
    if not desert_patches:
        return elephant_patches[0]

    # Assuming the desert is a larger area and we want the closest elephant to the desert
    closest_to_desert = None
    min_distance = float('inf')

    for elephant in elephant_patches:
        for desert in desert_patches:
            dist = distance(elephant, desert)
            if dist < min_distance:
                min_distance = dist
                closest_to_desert = elephant

    return closest_to_desert

